<h4 class="mb-3">Cash Pickup / Paid out</h4>
<div class="alert alert-light border">Session <b><?= e($s['session_no']) ?></b> &middot; cash the system expects in your drawer now: <b><?= e(money($expected)) ?></b></div>
<form method="post" class="card card-body mb-3 needs-validation" novalidate><?= csrf_field() ?><div class="row g-2">
<div class="col-md-3"><label class="form-label small">What happened?</label><select name="type" class="form-select"><?php foreach ($types as $k => $t): ?><option value="<?= $k ?>"><?= e($t[3]) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><label class="form-label small">Amount</label><input type="number" step="0.01" min="0.01" name="amount" class="form-control" required></div>
<div class="col-md-4"><label class="form-label small">Reason</label><input name="reason" class="form-control" required minlength="3" maxlength="200" placeholder="e.g. Drawer over limit - moved to safe"></div>
<div class="col-md-3"><label class="form-label small">Supervisor (only if you lack permission)</label><div class="input-group"><input name="approver" class="form-control" placeholder="Username" autocomplete="off"><input type="password" name="approver_pass" class="form-control" placeholder="Password" autocomplete="new-password"></div></div></div>
<div class="mt-3"><button class="btn btn-primary once">Record</button></div></form>
<div class="card"><div class="card-header">This shift</div><table class="table table-sm mb-0"><tbody><?php foreach ($rows as $r): ?><tr><td><?= e(fmt_date($r['txn_date'], 'H:i')) ?></td><td><?= e(ucwords(str_replace('_', ' ', $r['type']))) ?></td><td><?= e($r['note']) ?></td><td class="text-end <?= $r['direction'] === 'in' ? 'text-success' : 'text-danger' ?>"><?= $r['direction'] === 'in' ? '+' : '-' ?><?= number_format($r['amount'], 2) ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td class="text-muted text-center py-3">Nothing recorded yet.</td></tr><?php endif; ?></tbody></table></div>
